const btn=(text,action,data='',style='primary')=>`<button class="p-button ${style}" type="button" data-action="${action}" ${data}>${text}</button>`;
const badge=(status,text)=>`<span class="badge badge-${esc(status)}">${esc(text||label(status))}</span>`;
const tag=text=>`<span class="p-tag">${esc(text)}</span>`;
const empty=(title,text,action='')=>`<div class="empty-state"><span class="empty-icon">${icon('agents',28)}</span><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
