function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className='toast'+(error?' error':'');el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,6500);}
function filtered(rows){return query?rows.filter(row=>JSON.stringify(row).toLocaleLowerCase('pt-BR').includes(query)):rows;}
const records=kind=>S.records[kind]||[];
const get=(kind,id)=>records(kind).find(r=>r.id===id);

Object.assign(names,{requested:'Pedido registrado',understanding:'Entendendo o objetivo',producing:'Produção',reviewing:'Revisão',awaiting_approval:'Aguardando aprovação',ready:'Pronta para execução',executing:'Executando',verifying:'Verificando resultado',completed:'Concluída',measuring:'Acompanhando resultados',learned:'Aprendizado registrado',cancelled:'Cancelada',pending:'Pendente',revoked:'Revogada',verified:'Verificado'});
const operations=()=>S.operations||[];
const operationFor=r=>r?.operationId?operations().find(op=>op.id===r.operationId):null;
const operationStatus=op=>op.paused?'Pausada':label(op.state);
const operationBadge=r=>{const op=operationFor(r);return op?badge(op.state,operationStatus(op)):badge(r.status);};
const operationLink=r=>{const op=operationFor(r);return op?`<button class="operation-record-link" type="button" data-action="operation-detail" data-id="${esc(op.id)}">Operação · ${esc(operationStatus(op))} ↗</button>`:'';};
const safeEvidenceUrl=value=>/^https?:\/\//i.test(value||'')?value:'';
function operationRows(rows=operations()){return rows.map(op=>`<div class="operation-row" data-operation-id="${esc(op.id)}"><div><button type="button" class="row-title" data-action="operation-detail" data-id="${esc(op.id)}">${esc(op.objective)}</button><small>${esc(op.result?.summary||(op.blockers||[]).map(b=>b.message).join(' · ')||`${(op.artifactIds||[]).length} entregas registradas`)}</small></div>${badge(op.state,operationStatus(op))}</div>`).join('');}
function evidenceRows(rows){return rows.map(ev=>`<div class="operation-evidence-row">${badge(ev.status,ev.status==='recorded'&&ev.executor==='local'?'Registro local':undefined)}<div><strong>${esc(readableTerm(ev.executor||'Ferramenta'))}${ev.channel?' · '+esc(label(ev.channel)):''}</strong><p>${esc(ev.message||ev.error||'Registro da execução')}</p><small>${ev.occurredAt?fmtTime(ev.occurredAt):''}${ev.account?' · '+esc(ev.account):''}${ev.externalId?' · '+esc(ev.externalId):''}</small>${ev.uncertain?'<p class="operation-blocker">Resultado incerto. A ação não será repetida automaticamente.</p>':''}${safeEvidenceUrl(ev.url)?`<a class="subtle-link" href="${esc(ev.url)}" target="_blank" rel="noopener">Ver evidência ↗</a>`:''}</div></div>`).join('');}
function operationResults(){return operations().length?pane('Operações e evidências',operations().map(op=>`<article class="operation-result-entry">${operationRows([op])}${evidenceRows(op.evidence||[])}${!(op.evidence||[]).some(ev=>ev.status==='verified'&&ev.executor!=='local')?'<p class="micro-copy">Nenhuma execução externa comprovada. As entregas preparadas estão no Estúdio.</p>':''}</article>`).join('')):'';}
function selectApprovedAsset(id,selected=''){
 const op=operations().find(x=>x.id===id);if(!op)return;const activeCompany=org,expectedVersion=op.version,images=S.assets.filter(a=>a.mime?.startsWith('image/'));
 formDialog('Selecionar mídia aprovada','<p class="dialog-explainer wide">Vincule uma imagem real a esta mesma operação. A nova escolha invalida a revisão e a aprovação anteriores. Depois, retome a preparação; este passo não publica.</p>'+field('assetId','Imagem da biblioteca','select',selected||op.approvedAsset?.assetId||'',[['','Selecione uma imagem'],...images.map(a=>[a.id,a.name])],true)+'<div class="wide"><img id="approved-asset-preview" class="approved-asset-preview" alt="Prévia da imagem escolhida" hidden></div>'+field('approved','Confirmo que esta é a mídia aprovada para esta publicação.','checkbox',false).replace('type="checkbox"','type="checkbox" required')+'<p class="micro-copy wide">A primeira publicação aceita JPEG de feed, até 8 MB. A mídia precisa corresponder à identidade e às informações reais da empresa.</p><div class="wide"><button type="button" class="p-button secondary" data-action="upload-operation-asset">Enviar uma imagem</button><input id="operation-media-file" type="file" accept="image/jpeg,image/png,image/webp" hidden></div>',async d=>{if(org!==activeCompany)throw new Error('A empresa ativa mudou. Abra novamente a seleção.');if(d.approved!==true)throw new Error('Confirme a mídia aprovada antes de vincular.');await api(endpoint('operations/'+id+'/action'),'POST',{action:'select_asset',assetId:d.assetId,approved:true,expectedVersion});await conversationUI.reload?.();},'Vincular mídia aprovada',true);
 const preview=()=>{const asset=S.assets.find(a=>a.id===$('#f-assetId').value),image=$('#approved-asset-preview');image.hidden=!asset?.url;if(asset?.url)image.src=asset.url;else image.removeAttribute('src');};$('#f-assetId').addEventListener('change',preview);preview();
 $('#operation-media-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw new Error('Envie arquivos de até 25 MB.');if(org!==activeCompany)throw new Error('A empresa ativa mudou.');const asset=await uploadFile('/api/portal/'+activeCompany+'/files',file);if(org!==activeCompany)return;await refresh(false);selectApprovedAsset(id,asset.id);}catch(error){toast(error.message,true);}});
}
function publicationPreview(id){
 const op=operations().find(x=>x.id===id);if(!op)return;const p=op.publication||{},asset=S.assets.find(a=>a.id===p.assetId),quality=p.quality||{},blockers=op.blockers||[],ready=p.status==='ready_for_approval'&&!!p.snapshotId&&!blockers.length&&!op.paused&&!['executing','verifying','uncertain','completed','measuring','learned','cancelled'].includes(op.state);
 const check=(label,value,note)=>`<li><strong>${esc(label)}</strong><span>${value===true?'Conferido':value===false?'Pendente':'Revisão humana necessária'}</span>${note?`<small>${esc(note)}</small>`:''}</li>`;
 openDialog('Revisar publicação · '+S.company.name,`<div class="publication-preview"><p class="dialog-explainer">Confira a empresa, a conta, a mídia e a legenda desta versão. Aprovar entregas não publica; o botão final autoriza esta publicação.</p><dl class="publication-facts">${[['Empresa',S.company.name],['Conta',p.account?.username?'@'+p.account.username.replace(/^@/,'')+(p.account.id?' · '+p.account.id:''):'Conta ainda não confirmada'],['Canal e formato',(p.channel==='instagram'?'Instagram':p.channel||'Instagram')+' · '+(p.format==='image'?'Imagem':p.format||'Imagem')],['Executor',p.executor==='api'?'API do Instagram':p.executor||'Indisponível'],['Mídia',asset?.name||'Nenhuma mídia aprovada vinculada']].map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="publication-material">${asset?.url?`<figure><img src="${esc(asset.url)}" alt="Mídia aprovada: ${esc(asset.name)}"><figcaption>${esc(asset.name)}</figcaption></figure>`:'<p class="operation-blocker">Anexe uma imagem real na conversa e confirme que ela é a mídia aprovada para esta publicação.</p>'}<div><h3>Legenda desta versão</h3><p class="publication-caption">${esc(p.caption||'A legenda ainda não está pronta para revisão final.')}</p></div></div>${p.captionVersion||p.assetVersion?`<p class="micro-copy">Versão da mídia: ${esc(p.assetVersion||'—')} · Versão da legenda: ${esc(p.captionVersion?String(p.captionVersion).slice(0,12):'—')}</p>`:''}${Object.keys(quality).length?`<details class="operation-details" open><summary>Revisão da publicação</summary><ul class="publication-checks">${quality.technical?check('Técnica',quality.technical.passed,quality.technical.checks?.filter(c=>!c.passed).map(c=>c.note||c.label).join(' · ')):''}${quality.textual?check('Texto',quality.textual.passed,quality.textual.note):''}${quality.factual?check('Fatos e contexto',quality.factual.passed,quality.factual.note):''}${quality.visual?check('Imagem e identidade',quality.visual.passed,quality.visual.note):''}${quality.contextual?check('Revisão contextual',quality.contextual.approved,quality.contextual.summary):''}</ul><p class="micro-copy">${esc(quality.human?.note||'Confira pessoalmente os fatos, a identidade visual e o resultado antes de publicar.')}</p></details>`:''}${blockers.map(b=>`<p class="operation-blocker">${esc(b.message)}</p>`).join('')}${op.paused?'<p class="operation-blocker">Retome a operação antes de autorizar a publicação.</p>':''}<div class="operation-links"><a href="#/brand" data-action="close-dialog">Marca e negócio</a><a href="#/integrations" data-action="close-dialog">Integrações</a><a href="#/browser" data-action="close-dialog">Contas conectadas</a></div><p class="form-error publication-error" role="alert" hidden></p><div class="detail-actions">${btn('Aprovar e publicar agora','publication-approve',`data-id="${esc(id)}" data-company-id="${esc(S.company.id)}" data-snapshot-id="${esc(p.snapshotId||'')}" ${ready?'':'disabled'}`)}${btn('Atualizar revisão','publication-review',`data-id="${esc(id)}"`,'secondary')}</div><p class="micro-copy">A aprovação vale para esta conta, mídia e legenda. Mudanças exigem uma nova revisão. O resultado será confirmado com evidência do canal.</p></div>`,true);
}
function operationDetail(id){const op=operations().find(x=>x.id===id);if(!op)return;const terminal=['completed','learned','cancelled'].includes(op.state);openDialog('Operação da '+S.company.name,`<div class="operation-dialog"><div class="job-detail-meta">${badge(op.state,operationStatus(op))}<span>${fmtTime(op.updatedAt)}</span></div><h3>${esc(op.objective)}</h3>${(op.blockers||[]).map(b=>`<p class="operation-blocker">${esc(b.message)}</p>`).join('')}${op.result?.summary?`<p>${esc(op.result.summary)}</p>`:''}${op.result?.measurement?`<p>${esc(op.result.measurement)}</p>`:''}${op.approval?.at?`<p class="micro-copy">Aprovação registrada em ${fmtTime(op.approval.at)}.</p>`:''}${op.quality?.checks?.length?`<details class="operation-details"><summary>Controle de qualidade</summary><ul>${op.quality.checks.map(check=>`<li>${esc(check.label)} · ${check.requiresHuman?(op.approval?.status==='approved'?'Aprovação humana registrada':'Revisão humana necessária'):check.passed?'Conferido':'Pendente'}</li>`).join('')}</ul><p class="micro-copy">As verificações automáticas conferem a completude. Revise os fatos e a identidade antes de aprovar.</p></details>`:''}<h3>Plano</h3><ol class="operation-plan">${(op.plan||[]).map(step=>`<li><span>${esc(step.title)}</span>${badge(step.status)}<small>${esc(op.competencies?.find(c=>c.id===step.competency)?.name||step.competency||'')}</small></li>`).join('')}</ol>${op.competencies?.length?`<details class="operation-details"><summary>Competências mobilizadas</summary>${op.competencies.map(c=>`<p><strong>${esc(c.name)}</strong><br>${esc(c.responsibility)}${c.expected?'<br>Entrega: '+esc(c.expected):''}${c.criteria?'<br>Conclusão: '+esc(Array.isArray(c.criteria)?c.criteria.join('; '):c.criteria):''}</p>`).join('')}</details>`:''}<div class="operation-deliveries">${(op.artifactIds||[]).flatMap(id=>['content','pages','knowledge'].map(kind=>({kind,item:get(kind,id)}))).filter(x=>x.item).map(({kind,item})=>btn(esc(item.title),kind==='content'?'content-detail':'edit-record',`data-id="${esc(item.id)}" data-kind="${kind}"`,'secondary')).join('')}</div><h3>Evidências</h3>${(op.evidence||[]).length?evidenceRows(op.evidence):'<p class="micro-copy">Nenhuma execução externa comprovada nesta operação.</p>'}<div class="detail-actions">${op.firstInstagram&&op.state==='uncertain'?btn('Vincular publicação encontrada','link-publication',`data-id="${esc(op.id)}"`,'secondary'):''}${op.state==='uncertain'?btn('Conferir resultado','operation-action',`data-id="${esc(op.id)}" data-operation-action="verify"`,'secondary'):''}${op.state==='completed'?btn('Acompanhar resultados','operation-action',`data-id="${esc(op.id)}" data-operation-action="measure"`,'secondary'):''}${op.state==='measuring'?btn('Registrar aprendizado','operation-action',`data-id="${esc(op.id)}" data-operation-action="learn"`,'secondary'):''}${op.state==='awaiting_approval'&&!op.paused?btn('Aprovar entregas','operation-action',`data-id="${esc(op.id)}" data-operation-action="approve"`,'secondary'):''}${!op.firstInstagram&&op.artifactIds.some(id=>get('content',id))&&op.state==='ready'&&!op.paused?btn('Executar publicação','operation-action',`data-id="${esc(op.id)}" data-operation-action="execute"`,'secondary'):''}${op.firstInstagram&&!op.paused&&['blocked','ready','reviewing','awaiting_approval','failed'].includes(op.state)?btn('Selecionar mídia aprovada','select-operation-asset',`data-id="${esc(op.id)}"`,'secondary'):''}${op.firstInstagram&&!op.paused&&!['executing','verifying','uncertain','completed','measuring','learned','cancelled'].includes(op.state)?btn('Revisar publicação','publication-review',`data-id="${esc(op.id)}"`,'secondary'):''}${!terminal&&op.state!=='uncertain'?btn(op.paused||['blocked','failed'].includes(op.state)?'Retomar operação':'Pausar operação','operation-action',`data-id="${esc(op.id)}" data-operation-action="${op.paused||['blocked','failed'].includes(op.state)?'resume':'pause'}"`,'ghost'):''}${op.threadId?btn('Abrir conversa','operation-conversation',`data-id="${esc(op.threadId)}"`,'ghost'):''}</div></div>`,true);}
let policyRuleSequence=0;
function operationRuleRow(rule={channel:'*',action:'publish',risk:'high',policy:'approval_required'}){const id=++policyRuleSequence,options={channel:[['*','Todos os canais'],['openai','OpenAI · imagens'],['instagram','Instagram'],['whatsapp','WhatsApp'],['google','Google'],['metaAds','Meta Ads'],['website','Site'],['other','Outro']],action:[['*','Todas as ações'],['publish','Publicar conteúdo'],['send','Enviar mensagem'],['image','Gerar imagem'],['video','Gerar vídeo'],['alter_campaign','Alterar campanha'],['delete_content','Excluir conteúdo'],['delete_record','Excluir registro'],['change_profile','Alterar perfil'],['browser_action','Interagir no navegador']],risk:[['*','Todos os níveis'],['low','Baixo'],['medium','Médio'],['high','Alto']],policy:[['automatic','Automática'],['preauthorized','Previamente autorizada'],['approval_required','Exige aprovação'],['forbidden','Proibida']]};return `<div class="operation-rule" data-operation-rule>${Object.entries(options).map(([key,values])=>`<label class="p-field"><span>${{channel:'Canal',action:'Ação',risk:'Risco',policy:'Política'}[key]}</span><select id="operation-rule-${id}-${key}" data-rule-field="${key}">${values.map(([value,title])=>`<option value="${value}" ${rule[key]===value?'selected':''}>${title}</option>`).join('')}</select></label>`).join('')}<button type="button" class="quiet-button" data-action="remove-operation-rule" aria-label="Remover esta regra">Remover</button></div>`;}
function operationPolicyEditor(p){return `<section class="panel form-panel"><div class="form-section-heading"><span>03</span><div><h2>Permissões das operações</h2><p>Regras desta empresa, por canal, ação e risco.</p></div></div><div id="operation-policy-rules">${(p.operationRules||[]).map(operationRuleRow).join('')}</div>${btn('+ Adicionar regra','add-operation-rule','','secondary')}<p class="micro-copy">A regra mais específica prevalece. Em caso de empate, vale a mais restritiva. Uma autorização não confirma conexão ou publicação: o canal e o resultado continuam sendo verificados.</p></section>`;}
function readOperationRules(form){return [...form.querySelectorAll('[data-operation-rule]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-rule-field]')].map(select=>[select.dataset.ruleField,select.value])));}

const pendingJobs=()=>S.jobs.filter(j=>['queued','working','waiting_provider'].includes(j.state));
const asset=id=>S.assets.find(a=>a.id===id);
function pageHead(kicker,title,description='',actions=''){return `<div class="page-heading"><div><p class="overline">${esc(kicker)}</p><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div><div class="page-actions">${actions}</div></div>`;}
function pane(title,body,extra='',className=''){return `<section class="panel ${className}"><div class="panel-heading"><h2>${esc(title)}</h2>${extra}</div>${body}</section>`;}
function readiness(){const p=S.company.profile;return [{done:!!p.description&&!!p.audience,title:'Apresente o seu negócio',text:'O que você vende e quem deseja alcançar.',view:'brand'},{done:!!p.visualIdentity&&!!p.tone,title:'Defina a personalidade da marca',text:'Identidade, linguagem e diferenciais.',view:'brand'},{done:S.integrations.some(c=>c.id==='openai'&&c.verifiedAt&&c.validation?.status==='validated'),title:'Conecte a inteligência',text:'Ative o raciocínio dos agentes.',view:'integrations'},{done:S.integrations.some(c=>['instagram','whatsapp','google'].includes(c.id)&&c.verifiedAt),title:'Conecte os seus canais',text:'Traga os pontos de contato para a operação.',view:'integrations'}];}
function overview(){const ready=readiness(),done=ready.filter(r=>r.done).length;const counts=[['Conteúdos',records('content').length,'studio','Na sua biblioteca'],['Campanhas',records('campaigns').length,'campaigns','Organizadas no portal'],['Oportunidades',records('leads').filter(l=>!['lost','won'].includes(l.stage)).length,'leads','Em acompanhamento'],['Tarefas abertas',records('tasks').filter(t=>t.status!=='done').length,'tasks','Próximos movimentos']];return pageHead('SEU CENTRO DE MARKETING','Seu marketing, em movimento.',S.company.name+' · estratégia, criação e execução no mesmo lugar.',btn('+ Novo conteúdo','new-content')+btn('Criar campanha','new-campaign','','secondary'))+`<div class="stat-grid">${counts.map(([title,n,v,caption])=>`<a class="stat-card" href="#/${v}"><div><span>${title}</span>${icon(v)}</div><strong>${number(n)}</strong><small>${caption}</small></a>`).join('')}</div>`+operationalStatus()+routineNotice()+(done<4?`<section class="onboarding-panel"><div><span class="overline">PREPARE SUA OPERAÇÃO</span><h2>O contexto certo muda tudo.</h2><p>Conte para a Helpu como a sua empresa trabalha. Essa base orienta cada próximo movimento.</p><span class="onboarding-progress">${done} de 4 etapas concluídas</span></div><div class="onboarding-steps">${ready.map(r=>`<a href="#/${r.view}" class="onboarding-step ${r.done?'is-done':''}"><span>${r.done?'✓':'↗'}</span><div><strong>${r.title}</strong><small>${r.text}</small></div></a>`).join('')}</div></section>`:'')+`<div class="dashboard-grid">${pane('Próximos movimentos',records('tasks').filter(t=>t.status!=='done').slice(0,5).map(task=>taskRow(task)).join('')||empty('Um plano começa com o próximo passo.','Organize suas prioridades ou peça um plano ao diretor de marketing.',btn('Definir tarefa','new-task','','secondary')),`<a class="subtle-link" href="#/tasks">Ver todas ↗</a>`)}${pane('Sua equipe de agentes',`<div class="mini-agents">${S.agents.map(a=>`<button data-action="run-agent" data-id="${a.id}" class="mini-agent"><span class="agent-symbol">${icon('agents')}</span><div><strong>${esc(a.short)}</strong><small>${S.integrations.some(c=>c.id==='openai'&&c.verifiedAt&&c.validation?.status==='validated')?'Pronto para receber um objetivo':'Conecte a inteligência'}</small></div><span>↗</span></button>`).join('')}</div>`,badge(S.company.policy.enabled?'running':'paused',S.company.policy.enabled?'Rotina diária ativada':'Sob demanda'))}</div>`+(operations().length?pane('Objetivos em andamento',operationRows(operations().slice(0,5))):'')+pane('A operação em tempo real',jobsTable(S.jobs.slice(0,6)),`<a class="subtle-link" href="#/activity">Histórico completo ↗</a>`);}
function field(name,labelText,type='text',value='',options=[],required=false){const id='f-'+name;let input;if(type==='textarea')input=`<textarea id="${id}" name="${name}" rows="4" ${required?'required':''} maxlength="20000">${esc(value)}</textarea>`;else if(type==='select')input=`<select id="${id}" name="${name}" ${required?'required':''}>${options.map(o=>{const[v,l]=Array.isArray(o)?o:[o,label(o)];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;else if(type==='checkbox')return `<label class="checkline" for="${id}"><input id="${id}" type="checkbox" name="${name}" ${value?'checked':''}><span>${esc(labelText)}</span></label>`;else input=`<input id="${id}" name="${name}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="0" step="0.01"':''} ${required?'required':''} ${type==='password'?'autocomplete="off"':'maxlength="12000"'}>`;return `<label class="p-field ${type==='textarea'?'wide':''}" for="${id}"><span>${esc(labelText)}</span>${input}</label>`;}
function formFoot(text='Salvar alterações'){return `<p class="form-error" role="alert" hidden></p><div class="form-footer"><button type="submit" class="p-button primary">${text}</button><span>Informações salvas na sua empresa.</span></div>`;}
function provenanceField(name,labelText,...args){const html=field(name,labelText,...args),evidence=S.company.profileEvidence?.[name],source={supplied_by_user:'Informado por você',inferred:'Inferido — confirme antes de usar',unknown:'Origem não registrada',verified:'Fonte verificada',needs_confirmation:'Precisa de confirmação'}[evidence?.source]||'Origem não registrada';return html.replace(/<\/label>$/,`<small class="brand-source-note">${esc(source)}${evidence?.recordedAt?' · '+fmtTime(evidence.recordedAt):''}${evidence?.reference?' · '+esc(evidence.reference):''}</small></label>`);}
function brand(){const p=S.company.profile;return pageHead('MARCA E NEGÓCIO','A inteligência começa no contexto.','Esta é a memória da sua empresa. Os agentes usam estas informações para trabalhar.')+`<form id="brand-form" class="brand-form"><section class="panel form-panel"><div class="form-section-heading"><span>01</span><div><h2>Seu negócio</h2><p>Informações reais sobre o que você oferece.</p></div></div><div class="form-grid">${provenanceField('name','Nome da empresa','text',S.company.name,[],true)}${provenanceField('website','Site','url',p.website)}${provenanceField('description','O que a empresa vende e como funciona','textarea',p.description,[],true)}${provenanceField('offer','Produtos, serviços, preços e condições confirmados','textarea',p.offer)}${provenanceField('location','Região de atuação','text',p.location)}${provenanceField('salesProcess','Como a venda acontece','textarea',p.salesProcess)}</div></section><section class="panel form-panel"><div class="form-section-heading"><span>02</span><div><h2>Público e posicionamento</h2><p>Quem você atende e por que sua oferta importa.</p></div></div><div class="form-grid">${provenanceField('audience','Público, necessidades e principais dúvidas','textarea',p.audience,[],true)}${provenanceField('differentials','Diferenciais comprovados','textarea',p.differentials)}${provenanceField('positioning','Posicionamento e proposta de valor','textarea',p.positioning)}${provenanceField('competitors','Concorrentes e referências','textarea',p.competitors)}</div></section><section class="panel form-panel"><div class="form-section-heading"><span>03</span><div><h2>Identidade e direção</h2><p>Uma marca consistente em todas as entregas.</p></div></div><div class="form-grid">${provenanceField('tone','Tom de voz','text',p.tone)}${provenanceField('visualIdentity','Cores, tipografia e direção visual','textarea',p.visualIdentity)}${provenanceField('goals','Objetivos de marketing','textarea',p.goals)}${provenanceField('restrictions','O que a marca não deve dizer, prometer ou fazer','textarea',p.restrictions)}</div>${formFoot()}</section></form>`+companyDiagnosisCard(S,{esc,formatTime:fmtTime})+pane('Conhecimento complementar',records('knowledge').map(k=>`<div class="list-row"><div><strong>${esc(knowledgeTitle(k.title))}</strong><small>${esc(k.source||'Informação fornecida')}</small></div>${btn('Editar','edit-record',`data-kind="knowledge" data-id="${k.id}"`,'ghost')}</div>`).join('')||empty('Reúna o conhecimento da empresa.','Adicione orientações de atendimento, informações de produtos e referências.'),btn('+ Adicionar','new-knowledge','','secondary'));}
function campaignView(){const rows=filtered(records('campaigns'));return pageHead('CAMPANHAS','Uma direção para cada movimento.','Organize objetivo, oferta, público e entregas antes da execução.',btn('Criar campanha','new-campaign'))+(rows.length?`<div class="campaign-grid">${rows.map(c=>`<article class="panel campaign-card"><div class="card-top">${operationBadge(c)}<button class="icon-button" data-action="edit-record" data-kind="campaigns" data-id="${c.id}" aria-label="Editar ${esc(c.name)}">↗</button></div><h2>${esc(c.name)}</h2>${operationLink(c)}<p>${esc(c.objective||'Defina um objetivo para orientar a campanha.')}</p><div class="tags">${(c.channels||[]).map(x=>tag(label(x))).join('')}</div><div class="campaign-meta"><span><small>Orçamento planejado</small><strong>${money(c.budget)}</strong></span><span><small>Período</small><strong>${fmtDate(c.startDate)} → ${fmtDate(c.endDate)}</strong></span></div><div class="card-footer"><span>${records('content').filter(x=>x.campaignId===c.id).length} conteúdos</span>${btn('Criar briefing','campaign-brief',`data-id="${c.id}"`,'ghost')}</div>${!c.providerId?btn('Preparar no Meta Ads','meta-campaign',`data-id="${c.id}"`,'secondary'):''}${c.providerId?`<p class="micro-copy">Meta Ads: ${esc(c.providerStatus||'PAUSED')} · ${esc(c.providerId)}</p>`:''}</article>`).join('')}</div>`:empty('Sua próxima campanha começa aqui.','Defina o que você quer alcançar. A Helpu organiza as entregas em torno desse objetivo.',btn('Criar primeira campanha','new-campaign')));}
function mediaPreview(content,large=false){const file=asset(content.assetId);if(file?.mime.startsWith('image/'))return `<img loading="lazy" src="${esc(file.url)}" alt="${esc(content.title)}">`;if(file?.mime.startsWith('video/'))return `<video src="${esc(file.url)}" ${large?'controls':''} preload="metadata" playsinline aria-label="${esc(content.title)}"></video>`;return `<div class="media-empty">${icon(content.format==='video'?'studio':'brand',32)}<span>${esc(label(content.format))}</span><small>${content.format==='text'?'Texto da sua marca':'Sua próxima criação'}</small></div>`;}
function studio(){let rows=filtered(records('content'));if(studioFilter!=='all')rows=rows.filter(c=>c.format===studioFilter);return pageHead('BIBLIOTECA','Tudo o que sua marca cria.','Conteúdos, campanhas e arquivos, reunidos em um só lugar.','<a class="p-button primary" href="#/create">Criar com o Astra</a>'+btn('+ Conteúdo','new-content','','secondary')+btn('Enviar arquivo','upload','','ghost')+btn('Materiais oficiais','studio-materials','','secondary'))+studioUI.summary()+`<div class="filter-bar"><div class="filter-tabs" role="group" aria-label="Formato">${[['all','Todos'],['image','Imagens'],['video','Vídeos'],['story','Stories'],['text','Textos'],['carousel','Carrosséis']].map(([v,l])=>`<button data-action="studio-filter" data-id="${v}" class="${v===studioFilter?'active':''}" aria-pressed="${v===studioFilter}">${l}</button>`).join('')}</div><span>${rows.length} conteúdos</span></div>`+(rows.length?`<div class="content-grid">${rows.map(c=>`<article class="content-card"><button class="content-thumbnail" data-action="content-detail" data-id="${c.id}" aria-label="Abrir ${esc(c.title)}">${mediaPreview(c)}</button><div class="content-card-body"><div class="card-top">${tag(label(c.channel))}${operationBadge(c)}</div><h2>${esc(c.title)}</h2>${operationLink(c)}<p>${esc((c.caption||'Adicione uma legenda ou um briefing para começar.').slice(0,135))}</p><div class="card-footer"><span>${fmtDate(c.scheduledAt||c.createdAt)}</span>${btn('Abrir','content-detail',`data-id="${c.id}"`,'ghost')}</div></div></article>`).join('')}</div>`:empty(query?'Nenhum conteúdo encontrado.':'Cada criação começa com uma boa ideia.','Crie um briefing, escreva seu conteúdo ou envie os materiais da empresa.',btn('Criar com IA','create-ai')))+pane('Biblioteca da empresa',S.assets.length?`<div class="asset-grid">${S.assets.map(a=>`<a class="asset-tile" href="${esc(a.url)}" target="_blank" rel="noopener"><span>${a.mime.startsWith('image/')?`<img src="${esc(a.url)}" alt="" loading="lazy">`:icon('studio',26)}</span><strong>${esc(a.name)}</strong><small>${number(a.size/1024)} KB · ${a.mime.split('/')[1].toUpperCase()}</small></a>`).join('')}</div>`:empty('Seus materiais, organizados.','Guarde logos, fotos, vídeos e documentos para consulta e criação.'),btn('Enviar arquivo','upload','','secondary'));}
function calendar(){const year=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),offset=(first.getDay()+6)%7;const cells=[];for(let i=0;i<offset;i++)cells.push('<div class="calendar-cell outside"></div>');const today=new Date().toDateString();for(let day=1;day<=last.getDate();day++){const date=new Date(year,month,day),dateKey=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const items=records('content').filter(c=>c.scheduledAt&&new Date(c.scheduledAt).toDateString()===date.toDateString());cells.push(`<div class="calendar-cell ${date.toDateString()===today?'today':''}"><button class="day-number" data-action="schedule-day" data-date="${dateKey}" aria-label="Agendar em ${day}">${day}</button>${items.map(c=>`<button class="calendar-event ${c.status==='published'?'is-published':''}" data-action="content-detail" data-id="${c.id}"><small>${esc(label(c.channel))}${operationFor(c)?" · "+esc(operationStatus(operationFor(c))):""}</small>${esc(c.title)}</button>`).join('')}</div>`);}return pageHead('CALENDÁRIO EDITORIAL','Consistência também se planeja.','Organize os próximos conteúdos. Horários exibidos conforme este computador.',btn('Agendar conteúdo','schedule'))+`<section class="panel calendar-panel"><div class="calendar-toolbar"><div><h2>${calendarDate.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2></div><div>${btn('Hoje','calendar-today','','ghost')}${btn('←','calendar-prev','','secondary')}${btn('→','calendar-next','','secondary')}</div></div><div class="calendar-week">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div></section>`;}
const leadStages=['new','qualified','proposal','won','lost'];
function leads(){const rows=filtered(records('leads'));return pageHead('CONTATOS E FUNIL','Oportunidades em boas mãos.','Acompanhe a evolução de cada contato e o próximo passo da conversa.',btn('+ Novo contato','new-lead')+btn('Campanha de mensagens','bulk-message','','secondary')+btn('Importar CSV','import-leads','','secondary')+`<a class="p-button ghost" href="${endpoint('export?kind=leads')}">Exportar</a>`)+`<div class="pipeline-summary"><span><strong>${rows.length}</strong> contatos registrados</span><span><strong>${money(rows.filter(l=>l.stage==='won').reduce((n,l)=>n+(l.value||0),0))}</strong> valor informado em negócios ganhos</span></div><div class="kanban">${leadStages.map(stage=>{const items=rows.filter(l=>l.stage===stage);return `<section class="kanban-column"><div class="kanban-heading"><h2>${label(stage)}</h2><span>${items.length}</span></div>${items.map(l=>`<article class="lead-card"><button class="lead-title" data-action="edit-record" data-kind="leads" data-id="${l.id}">${esc(l.name)}</button><p>${esc(l.company||l.email||l.phone||'Sem empresa informada')}</p>${l.value?`<strong class="lead-value">${money(l.value)}</strong>`:''}<span class="source-label">${esc(l.source||'Registro manual')}</span>${l.nextAction?`<div class="next-action">↗ ${esc(l.nextAction)}<small>${fmtDate(l.nextDate)}</small></div>`:''}<div class="lead-controls"><select data-lead-stage="${l.id}" aria-label="Etapa de ${esc(l.name)}">${leadStages.map(s=>`<option value="${s}" ${l.stage===s?'selected':''}>${label(s)}</option>`).join('')}</select><button class="icon-button" data-action="open-conversation" data-id="${l.id}" aria-label="Conversa com ${esc(l.name)}">${icon('inbox',17)}</button></div></article>`).join('')||'<p class="column-empty">Os contatos desta etapa aparecem aqui.</p>'}</section>`;}).join('')}</div><p class="micro-copy">A importação de contatos não registra autorização para mensagens. Atualize a permissão com base no consentimento recebido.</p>`;}
function inbox(){const leads=filtered(records('leads'));if(!selectedLead||!records('leads').some(l=>l.id===selectedLead))selectedLead=leads[0]?.id||'';const lead=get('leads',selectedLead),messages=records('messages').filter(m=>m.leadId===selectedLead).reverse();return pageHead('ATENDIMENTO','Cada conversa tem um próximo passo.','Histórico, respostas e acompanhamento no contexto da sua empresa.')+`<section class="inbox-shell"><aside class="conversation-list"><div class="inbox-label">CONTATOS <span>${leads.length}</span></div>${leads.map(l=>`<button data-action="select-lead" data-id="${l.id}" class="conversation-item ${l.id===selectedLead?'active':''}"><span class="avatar">${esc(l.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(l.name)}</strong><small>${esc(l.company||l.source||'Contato')}</small></div></button>`).join('')||empty('Nenhum contato.','Adicione um contato ou conecte um canal.',btn('Adicionar','new-lead','','secondary'))}</aside><div class="conversation-main">${lead?`<div class="conversation-head"><div><h2>${esc(lead.name)}</h2><p>${esc(lead.email||lead.phone||'Sem informação de contato')}</p></div>${badge(lead.optOut?'blocked':lead.stage,lead.optOut?'Mensagens interrompidas':label(lead.stage))}</div><div class="messages">${messages.map(m=>`<div class="message ${m.direction==='incoming'?'incoming':'outgoing'}"><p>${esc(m.text)}</p>${operationLink(m)}<div><span>${esc(label(m.channel))} · ${esc(label(m.status))}</span><span>${fmtTime(m.createdAt)}</span></div>${m.direction==='outgoing'&&m.status==='draft'?`<button class="message-send" data-action="send-message" data-id="${m.id}">Enviar pelo canal ↗</button>`:''}</div>`).join('')||'<div class="conversation-empty">O histórico deste contato começa aqui.</div>'}</div><form id="message-form" class="message-composer"><div class="composer-options">${field('channel','Canal','select','whatsapp',[['whatsapp','WhatsApp'],['instagram','Instagram']])}${btn('Sugerir com IA','reply-ai',`data-id="${lead.id}"`,'ghost')}${btn('Registrar recebida','record-incoming',`data-id="${lead.id}"`,'ghost')}</div><textarea name="text" placeholder="Escreva uma resposta…" aria-label="Resposta ao contato" required maxlength="20000"></textarea><details class="template-details"><summary>Usar modelo aprovado do WhatsApp</summary><div class="form-grid">${field('template','Nome do modelo')}${field('language','Idioma','text','pt_BR')}${field('parameters','Variáveis do modelo, uma por linha','textarea')}</div></details><div class="composer-footer"><span>Salvar não envia a mensagem.</span><button class="p-button primary" type="submit">Salvar resposta</button></div><p class="form-error" role="alert" hidden></p></form>`:empty('Seu atendimento em um só lugar.','Selecione um contato para abrir o histórico.')}</div></section>`;}
function pages(){return pageHead('CAPTAÇÃO','Transforme interesse em conversa.','Crie páginas simples de interesse que alimentam o funil da empresa.',btn('Criar página de captação','new-page'))+`<div class="notice-inline">${icon('pages')}<p>${S.company.policy.publicBaseUrl?'Endereço público configurado: '+esc(S.company.policy.publicBaseUrl):'As páginas funcionam neste computador. Para receber contatos externos, o portal precisa estar publicado em um endereço HTTPS.'}</p></div>`+(records('pages').length?`<div class="campaign-grid">${filtered(records('pages')).map(p=>`<article class="panel campaign-card"><div class="card-top">${badge(p.active?'running':'paused',p.active?'Disponível':'Pausada')}${btn('Editar','edit-record',`data-kind="pages" data-id="${p.id}"`,'ghost')}</div><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><div class="card-footer"><a class="subtle-link" href="/capture/${p.id}" target="_blank" rel="noopener">Abrir página ↗</a>${btn('Copiar link','copy-capture',`data-id="${p.id}"`,'secondary')}</div></article>`).join('')}</div>`:empty('Uma porta de entrada para novas oportunidades.','O formulário salva os contatos diretamente no funil desta empresa.',btn('Criar primeira página','new-page')));}
function agents(){return pageHead('SUA EQUIPE DE AGENTES','Especialidades conectadas.','Cada agente trabalha com a memória da empresa e entrega um resultado rastreável.',btn('Definir rotina','go-settings','','secondary'))+`<div class="agent-grid">${S.agents.map(a=>{const jobs=S.jobs.filter(j=>j.kind==='agent'&&j.payload.agent===a.id),last=jobs[0];return `<article class="panel agent-card"><div class="agent-card-top"><span class="agent-symbol">${icon('agents',24)}</span>${last?badge(last.state):tag('Sob demanda')}</div><h2>${esc(a.name)}</h2><p>${esc(a.description)}</p><div class="agent-last"><small>ÚLTIMA ENTREGA</small><span>${last?fmtTime(last.updatedAt):'Ainda não executado'}</span></div>${btn('Dar um objetivo ↗','run-agent',`data-id="${a.id}"`,'secondary')}</article>`;}).join('')}</div>`+pane('Entregas e execuções',jobsTable(S.jobs.filter(j=>j.kind==='agent')));}
function taskRow(t){return `<div class="task-row"><button class="task-check ${t.status==='done'?'checked':''}" ${t.kernelStep?'disabled title="Etapa controlada pela operação"':''} data-action="toggle-task" data-id="${t.id}" aria-label="${t.status==='done'?'Reabrir':'Concluir'} ${esc(t.title)}">${t.status==='done'?'✓':''}</button><div><button class="row-title" data-action="edit-record" data-kind="tasks" data-id="${t.id}">${esc(t.title)}</button><small>${esc(t.description||'Sem descrição')}</small>${operationLink(t)}</div>${badge(t.priority==='high'?'review':'draft',label(t.priority))}<span class="row-date">${fmtDate(t.dueDate)}</span></div>`;}
function tasks(){const rows=filtered(records('tasks'));return pageHead('ORGANIZAÇÃO','Próximos passos, bem definidos.','Mantenha prioridades, entregas e pendências em movimento.',btn('Criar tarefa','new-task'))+pane('Tarefas da operação',rows.length?rows.sort((a,b)=>(a.status==='done')-(b.status==='done')).map(taskRow).join(''):empty('O próximo passo está nas suas mãos.','Crie uma tarefa ou solicite um plano ao diretor de marketing.',btn('Criar tarefa','new-task','','secondary')));}
function instagramSnapshots(rows){
 const snapshots=rows.filter(r=>r.snapshot&&typeof r.snapshot==='object').sort((a,b)=>new Date(b.snapshot.observedAt||b.importedAt||b.date)-new Date(a.snapshot.observedAt||a.importedAt||a.date));if(!snapshots.length)return '';
 const labels={reach:'Alcance',views:'Visualizações',likes:'Curtidas',comments:'Comentários',saved:'Salvamentos',shares:'Compartilhamentos'},periods={initial:'Consulta inicial','1h':'Consulta de 1 hora','24h':'Consulta de 24 horas','7d':'Consulta de 7 dias'};
 return pane('Métricas do Instagram',`<p class="micro-copy padded">Cada consulta preserva o acumulado informado pelo Instagram naquele momento. Consultas de 1 hora, 24 horas e 7 dias são exibidas separadamente e não são somadas aos totais.</p>${snapshots.map(r=>{const snapshot=r.snapshot,op=operationFor(r),at=snapshot.observedAt||r.importedAt,values=Array.isArray(snapshot.metrics)?snapshot.metrics:[],missing=Array.isArray(snapshot.unavailable)?snapshot.unavailable:[],names=[...new Set([...Object.keys(labels),...values.map(m=>m.name),...missing.map(m=>m.name)].filter(Boolean))];return `<article class="operation-result-entry" data-metric-snapshot="${esc(r.id)}"><div class="operation-row"><div><strong class="row-title">${esc(periods[r.period]||r.period||'Consulta registrada')}</strong><small>${esc(op?.objective||get('campaigns',r.campaignId)?.name||'Publicação no Instagram')}${at?' · '+fmtTime(at):''} · ${esc(r.source||'Fonte não informada')}</small>${operationLink(r)}</div>${badge(snapshot.status,{partial:'Dados parciais',verified:'Dados retornados',unavailable:'Indisponível'}[snapshot.status]||'Consulta registrada')}</div><div class="table-wrap"><table><thead><tr><th>Métrica</th><th>Valor retornado</th><th>Fonte / observação</th></tr></thead><tbody>${names.map(name=>{const value=values.find(m=>m.name===name),available=typeof value?.value==='number'&&Number.isFinite(value.value),reason=missing.find(m=>m.name===name)?.reason;return `<tr data-metric-name="${esc(name)}"><td>${esc(labels[name]||name)}</td><td data-metric-value>${available?number(value.value):'—'}</td><td>${available?esc(value.source||r.source||'Fonte não informada'):esc(reason||'Não retornado nesta consulta.')}${available&&(value.observedAt||at)?`<small>${fmtTime(value.observedAt||at)}</small>`:''}${value?.mediaId?`<small style="max-width:none;white-space:normal;overflow-wrap:anywhere">Publicação: ${esc(value.mediaId)}${value.accountId?' · Conta: '+esc(value.accountId):''}</small>`:''}</td></tr>`;}).join('')}</tbody></table></div></article>`;}).join('')}`);
}
function results(){const allRows=filtered(records('metrics')),rows=allRows.filter(r=>!r.snapshot),sum=key=>{const vals=rows.filter(r=>r[key]!==null&&r[key]!==undefined);return vals.length?vals.reduce((n,r)=>n+Number(r[key]),0):null;};const spend=sum('spend'),revenue=sum('revenue'),clicks=sum('clicks'),impressions=sum('impressions');const chartRows=[...rows].sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(-12);const max=Math.max(1,...chartRows.map(r=>r.clicks||0));return pageHead('RESULTADOS','Clareza para o próximo movimento.','Acompanhe medições registradas e dados confirmados pelos canais.',btn('Registrar medição','new-metric')+btn('Importar Meta Ads','import-metrics','','secondary'))+`<div class="stat-grid"><div class="stat-card"><span>Impressões</span><strong>${number(impressions)}</strong><small>${rows.length?'Nas medições gerais':allRows.length?'Não informado nas medições gerais':'Sem medições'}</small></div><div class="stat-card"><span>Cliques</span><strong>${number(clicks)}</strong><small>Interesse registrado</small></div><div class="stat-card"><span>Investimento</span><strong>${money(spend)}</strong><small>Valor medido, não orçamento</small></div><div class="stat-card"><span>Receita informada</span><strong>${money(revenue)}</strong><small>Não implica atribuição à campanha</small></div></div>`+operationResults()+instagramSnapshots(allRows)+pane('Cliques por medição',chartRows.length?`<div class="chart-wrap"><svg viewBox="0 0 700 200" role="img" aria-label="Cliques por medição registrada"><path d="M30 170H680" stroke="#ddd7cd"/>${chartRows.map((r,i)=>{const w=620/chartRows.length,x=40+i*w,h=(r.clicks||0)/max*125;return `<g><rect x="${x}" y="${170-h}" width="${Math.max(8,w-16)}" height="${h}" rx="3" fill="#ff571f"/><text x="${x}" y="190" fill="#74716b" font-size="10">${esc(fmtDate(r.date))}</text><text x="${x}" y="${160-h}" fill="#24221e" font-size="11">${number(r.clicks)}</text></g>`;}).join('')}</svg></div>`:empty('Sem números inventados.','Conecte o Meta Ads ou registre uma medição para começar a acompanhar resultados.'))+pane('Medições e fontes',rows.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Canal / fonte</th><th>Impressões</th><th>Cliques</th><th>Investimento</th><th>Receita</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${esc(label(r.channel))}<small>${esc(label(r.source))}</small></td><td>${number(r.impressions)}</td><td>${number(r.clicks)}</td><td>${money(r.spend)}</td><td>${money(r.revenue)}</td><td>${r.source==='manual'?btn('Editar','edit-record',`data-kind="metrics" data-id="${r.id}"`,'ghost'):tag('Importado')}</td></tr>`).join('')}</tbody></table></div>`:empty('As fontes aparecem aqui.','Cada medição mantém sua origem e seu período.'))+`<p class="micro-copy">Medições de períodos sobrepostos podem se repetir nos totais. Use períodos distintos para comparar. Receita informada não é uma estimativa da IA.</p>`;}
function validationDetail(id){const integration=S.integrations.find(c=>c.id===id);if(!integration)return;const v=integration.validation?.status?integration.validation:null,identity=integration.identity?.username&&['identity_confirmed','identity_detected'].includes(integration.identity.status)?integration.identity:null;let html=`<p class="dialog-explainer">${esc(integration.name)} · ${v?esc({validated:'Validação concluída',blocked:'Validação bloqueada',failed:'Falha na validação'}[v.status]||readableTerm(v.status)):'Nenhuma validação operacional registrada.'}</p>`;if(v)html+=`<dl class="publication-facts">${[['Provedor',v.provider],['Modelo configurado',v.configuredModel],['Código do provedor',v.providerDiagnostic?.code],['ID da solicitação',v.providerDiagnostic?.requestId],['Modelo retornado',v.model],['Identificador da resposta',v.responseId],['Ferramentas do teste',Array.isArray(v.tools)?v.tools.map(t=>readableTerm(typeof t==='string'?t:t.name||t.type||'')).filter(Boolean).join(', '):''],['Início',v.startedAt?fmtTime(v.startedAt):''],['Conclusão',v.completedAt?fmtTime(v.completedAt):''],['Tempo de resposta',v.latencyMs!==undefined?v.latencyMs+' ms':''],['Saída estruturada',v.structuredOutput===true?'Validada':v.structuredOutput===false?'Não validada':''],['Chamada de ferramenta',v.toolCalling===true?'Validada':v.toolCalling===false?'Não validada':'']].filter(([,value])=>value!==undefined&&value!=='').map(([title,value])=>`<div><dt>${esc(title)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${v.error?`<p class="operation-blocker">${esc(v.error)}</p>`:''}`;if(identity)html+=`<section class="identity-summary"><h3>${esc(identity.username?'@'+identity.username.replace(/^@/,''):'Identidade da conta')}</h3><p>ID: ${esc(identity.accountId||identity.id)}</p><p>${identity.status==='identity_confirmed'?'Identidade confirmada por você em '+fmtTime(identity.confirmedAt):'Identidade detectada pelo serviço. Confira se esta conta pertence à empresa ativa.'}</p>${identity.status==='identity_detected'?btn('Confirmar esta conta para '+esc(S.company.name),'confirm-api-identity',`data-id="${esc(id)}" data-company-id="${esc(S.company.id)}" data-identity-id="${esc(identity.id||identity.accountId)}" data-username="${esc(identity.username)}"`,'secondary'):''}</section>`;html+='<p class="micro-copy">Validar acesso ou confirmar a conta não autoriza uma publicação. A mídia e a legenda serão revisadas na operação.</p>';openDialog('Validação · '+integration.name,html,true);}
function integrationProof(c){const identity=c.identity?.username&&['identity_confirmed','identity_detected'].includes(c.identity.status)?c.identity:null;return (identity?'<p class="integration-identity">@'+esc(identity.username)+' · '+(identity.status==='identity_confirmed'?'Conta confirmada':'Confira se esta é a conta da empresa')+'</p>':'')+(c.verifiedAt?'<small class="micro-copy">Última verificação: '+fmtTime(c.verifiedAt)+'</small>':'');}
function integrations(){
 const brain=S.integrations.find(c=>c.id==='openai');
 return pageHead('CRIAÇÃO E ENTREGA','Conteúdo pronto para você publicar.','A Helpu cria e entrega pelo WhatsApp. Você cuida da publicação no seu perfil.')+
 '<section class="panel connection-card"><h2>WhatsApp da Helpu</h2><p>Informe seu telefone na conversa, confirme o vínculo e ative ou desative o recebimento quando quiser. Você não precisa conectar o Instagram.</p><a class="p-button primary" href="#/conversation">Expandir para WhatsApp</a><p class="micro-copy">A ativação do número oficial é feita pela administração. Salvar o telefone não confirma a conexão.</p></section>'+
 (brain?'<details class="company-resources"><summary>Configuração da inteligência</summary><p>O Astra usa o serviço de IA configurado pela administração.</p>'+integrationProof(brain)+btn('Configurar Astra','configure-integration','data-id="openai"','secondary')+(brain.configured?btn('Verificar acesso','test-integration','data-id="openai"','ghost'):'')+'</details>':'')+'<div class="notice-box"><strong>Criação de conteúdo</strong><p>Escolha Feed, Story, Carrossel ou Reels e acompanhe o resultado na tela de criação.</p><a class="p-button secondary" href="#/create">Criar conteúdo</a></div>';
}
function instagramSetup(){openDialog('Preparar o login do Instagram',instagramSetupContent(S.connectionLogin?.instagram,esc));}

function settings(){const p=S.company.policy;return autonomySummary(S,esc)+routineNotice()+pageHead('AUTONOMIA','Você define a direção.','Escolha o que a operação pode executar e os limites de cada rotina.')+`<form id="settings-form"><section class="panel form-panel"><div class="form-section-heading"><span>01</span><div><h2>Rotina do Astra</h2><p>${S.worker?.local===false?'A rotina roda na nuvem e segue as permissões desta empresa.':'A rotina funciona enquanto o servidor da Helpu estiver aberto.'}</p></div></div><div class="toggle-list">${field('enabled','Executar o diretor de marketing uma vez por dia','checkbox',p.enabled)}${field('autoMedia','Gerar imagens para os conteúdos criados pelos agentes','checkbox',p.autoMedia)}</div><p class="micro-copy">Crie pelo painel ou pelo WhatsApp vinculado. Revise os materiais e publique manualmente. Cada execução fica no histórico.</p></section><section class="panel form-panel"><div class="form-section-heading"><span>02</span><div><h2>Limites e horário</h2><p>Uma rotina alinhada à capacidade da sua empresa.</p></div></div><div class="form-grid">${p.usageTestingEnabled===true?field('unlimitedUsage','Sem limite de uso interno (fase de testes)','checkbox',['dailyRuns','dailyMedia','dailyMessages'].every(k=>p[k]==='unlimited')):''}${field('dailyRuns','Execuções de IA por dia','number',p.dailyRuns==='unlimited'?'':p.dailyRuns)}${field('dailyMedia','Gerações de mídia por dia','number',p.dailyMedia==='unlimited'?'':p.dailyMedia)}${field('dailyMessages','Envios de mensagens por dia','number',p.dailyMessages==='unlimited'?'':p.dailyMessages)}${field('timeZone','Fuso da rotina diária','select',p.timeZone,[['America/Sao_Paulo','Brasília'],['America/Manaus','Manaus'],['America/Rio_Branco','Rio Branco'],['Europe/Lisbon','Lisboa']])}${field('publicBaseUrl','Endereço HTTPS público do portal, quando publicado','url',p.publicBaseUrl)}</div><p class="micro-copy">Lembretes proativos ainda não estão disponíveis. O calendário registra a sua programação editorial.</p></section>${formFoot('Salvar autonomia')}</form><section class="panel form-panel"><h2>Uso interno</h2><p>Hoje: ${number(S.usage?.used?.dailyRuns??0)} execuções de IA e ${number(S.usage?.used?.dailyMedia??0)} gerações de mídia. Respostas no WhatsApp nas últimas 24 horas: ${number(S.usage?.whatsappRepliesLast24Hours??0)}.</p><p>Zerar reinicia os contadores internos da empresa e preserva o histórico. Não altera saldo, cobrança nem limites da OpenAI ou da Meta.</p>${p.usageTestingEnabled===true?btn('Zerar uso interno','reset-usage','','secondary'):''}${technicalUsageCard(S.usage?.technicalUsage,esc)}</section>`;}
function jobsTable(jobs){if(!jobs.length)return empty('A operação deixa um rastro claro.','Os próximos pedidos, resultados e pendências aparecem aqui.');return `<div class="table-wrap"><table><thead><tr><th>Execução</th><th>Situação</th><th>Agendada para</th><th>Atualização</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td><strong>${esc(jobTitle(j))}</strong><small>${esc((j.error||j.payload.brief||'').slice(0,105))}</small></td><td>${badge(j.state)}</td><td>${fmtTime(j.scheduledAt)}</td><td>${fmtTime(j.updatedAt)}</td><td>${btn('Abrir','job-detail',`data-id="${j.id}"`,'ghost')}</td></tr>`).join('')}</tbody></table></div>`;}
function jobTitle(j){if(j.kind==='agent')return S.agents.find(a=>a.id===j.payload.agent)?.name||'Agente';return {image:'Gerar imagem',video:'Gerar vídeo',publish:'Publicar conteúdo',send:'Enviar mensagem',insights:'Importar resultados',metaCampaign:'Criar campanha no Meta Ads',googlePresence:'Atualizar presença no Google'}[j.kind]||readableTerm(j.kind);}
function activity(){return pageHead('ATIVIDADES','Tudo o que move a operação.','Acompanhe pedidos, confirmações e mudanças da sua empresa.')+(operations().length?pane('Operações da conversa',operationRows(filtered(operations()))):'')+pane('Fila de execução',jobsTable(filtered(S.jobs)))+pane('Histórico da empresa',`<div class="audit-list">${S.audit.map(a=>`<div class="audit-row"><span class="audit-dot"></span><div><strong>${esc(a.action)}</strong><small>${esc(a.note)}</small></div><time>${fmtTime(a.created_at)}</time></div>`).join('')||'<p class="muted padded">Nenhuma atividade registrada.</p>'}</div>`);}
function render(){if(!S)return;document.body.dataset.view=view;const current=routes.find(n=>n[0]===view)||routes[0];$('#breadcrumb-page').textContent=current[1];$('#breadcrumb-company').textContent=S.company.name;$('#portal-nav').innerHTML=nav.map(([id,name])=>`<a href="#/${id}" class="nav-link ${sectionFor(view)===id?'active':''}" ${sectionFor(view)===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span></a>`).join('');const views={pricing:()=>pricingUI.page(),commercial:()=>commercialUI.page(true),proposals:()=>commercialUI.page(),consultations:()=>consultationUI.page(),'consultations-admin':()=>consultationUI.page(true),assisted:()=>assistedUI.page(),admin:()=>assistedUI.page(true),conversation:()=>conversationUI.chat(),company:companyHome,account:()=>accountUI.page(),browser:()=>S.worker?.local===false||S.runtime?.configured?cloudToolsUI.screens():conversationUI.accounts(),video:()=>creationUI.page('reels'),create:()=>creationUI.page(creationFormat),overview,brand,campaigns:campaignView,studio,calendar,leads,inbox,pages,agents,tasks,results,integrations,settings,activity,presence};$('#workspace').innerHTML=sectionTabs()+(views[view]||conversationUI.chat)();$('#sync-label').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});$('#worker-indicator').textContent=S.company.policy.enabled?'Rotina diária ativada':'Operação sob demanda';bindPageForms();conversationUI.mount(view==='browser'&&(S.worker?.local===false||S.runtime?.configured)?'remote-browser':view);accountUI.mount(view);assistedUI.mount(view);consultationUI.mount(view);commercialUI.mount(view);pricingUI.mount(view);onboardingUI.mount();contextualHelpUI.mount(view,creationFormat);cloudToolsUI.mount(view==='video'||view==='create'?'':view==='browser'&&S.worker?.local!==false&&!S.runtime?.configured?'local-browser':view);creationUI.mount(view==='video'||view==='create'?'create':view);}

function refreshInbox(){
 const previousLead=selectedLead,form=$('#message-form');if(!form)return;
 const template=document.createElement('template');template.innerHTML=inbox();
 if(previousLead!==selectedLead){render();return;}
 for(const selector of ['.conversation-list','.conversation-head','.messages']){
  const current=$('#workspace '+selector),next=template.content.querySelector(selector);if(!current||!next)continue;
  const atEnd=current.scrollHeight-current.clientHeight-current.scrollTop<48,top=current.scrollTop;
  current.replaceChildren(...next.childNodes);current.scrollTop=atEnd?current.scrollHeight:top;
 }
}
function operationalStatus(){
 const brain=S.integrations.find(c=>c.id==='openai'),verified=brain?.verifiedAt&&brain.validation?.status==='validated';
 const attention=S.jobs.filter(j=>['blocked','failed','uncertain'].includes(j.state)).length;
 return `<section class="operation-health" aria-label="Estado da operação"><a href="#/activity"><span>${S.worker?.local===false?'Executor na nuvem':'Executor local'}</span><strong>${S.worker?.running?'Em funcionamento':'Parado'}</strong><small>${S.worker?.lastTick?'Última verificação: '+fmtTime(S.worker.lastTick):'Aguardando primeira verificação'}</small></a><a href="#/integrations"><span>Inteligência</span><strong>${verified?'Validada':brain?.configured?'Validação pendente':'Conexão pendente'}</strong><small>${verified?'Raciocínio e ferramentas conferidos':esc(brain?.error||'Abra Integrações para configurar e testar.')}</small></a><a href="#/settings"><span>Rotina diária</span><strong>${S.company.policy.enabled?'Ativada':'Sob demanda'}</strong><small>${S.worker?.local===false?'Rotina na nuvem, conforme as permissões da empresa.':'Funciona enquanto o servidor estiver aberto'}</small></a><a href="#/activity"><span>Execuções recentes</span><strong>${attention?attention+' precisam de atenção':'Sem falhas pendentes'}</strong><small>Consulte os bloqueios e suas próximas ações</small></a></section>`;
}
let refreshSequence=0;async function refresh(renderPage=true){const companyId=org,sequence=++refreshSequence,previous=S;const next=await api(endpoint('state'));if(companyId!==org||sequence!==refreshSequence)return;S=next;if(!renderPage&&view==='brand'){const card=$('[data-company-diagnosis]');if(card)card.outerHTML=companyDiagnosisCard(S,{esc,formatTime:fmtTime});}if(renderPage)render();else if(view==='inbox'&&previous?.company.id===next.company.id&&JSON.stringify([previous.records.messages,previous.records.leads])!==JSON.stringify([next.records.messages,next.records.leads]))refreshInbox();}
function route(){let id=location.hash.replace(/^#\//,'')||'conversation';if(id==='video'||id==='create'||id.startsWith('create/')){const selection=id==='video'?'reels':id.split('/')[1];creationFormat=['feed','story','carousel','reels'].includes(selection)?selection:'feed';id='create';}view=['browser','presence'].includes(id)?'integrations':routes.some(n=>n[0]===id)?id:'conversation';query='';$('#global-search').value='';$('#sidebar').classList.remove('open');$('#sidebar-toggle').setAttribute('aria-expanded','false');render();}
function openDialog(title,html,wide=false){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#editor').classList.toggle('wide-dialog',wide);if(!$('#editor').open)$('#editor').showModal();$('#editor').scrollTop=0;$('#dialog-body').scrollTop=0;$('#dialog-close').focus({preventScroll:true});}
function closeDialog(){$('#editor').close();}
function formDialog(title,html,onSave,submitLabel='Salvar',wide=false){openDialog(title,`<form id="dialog-form"><div class="form-grid">${html}</div>${formFoot(submitLabel)}</form>`,wide);$('#dialog-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');submit.disabled=true;error.hidden=true;try{const d=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(c=>d[c.name]=c.checked);await onSave(d);closeDialog();await refresh();toast('Salvo na sua empresa.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{submit.disabled=false;}});}
const campaignOptions=()=>[['','Sem campanha'],...records('campaigns').map(c=>[c.id,c.name])];
function editRecord(kind,id=null,initial={}){const r=id?get(kind,id):initial;if(!r)return;let html='';const titles={campaigns:'Campanha',content:'Conteúdo',leads:'Contato',messages:'Mensagem',tasks:'Tarefa',metrics:'Medição',pages:'Página de captação',knowledge:'Conhecimento da empresa'};if(kind==='campaigns')html=field('name','Nome da campanha','text',r.name,[],true)+(r.operationId?operationLink(r):field('status','Etapa','select',r.status||'draft',['draft','planning','running','paused','complete']))+field('objective','Objetivo','textarea',r.objective)+field('audience','Público','textarea',r.audience)+field('offer','Oferta e mensagem principal','textarea',r.offer)+field('budget','Orçamento planejado (R$)','number',r.budget)+field('channels','Canais separados por vírgula','text',(r.channels||[]).join(', '))+field('startDate','Início','date',r.startDate)+field('endDate','Fim','date',r.endDate)+field('notes','Observações','textarea',r.notes);
 if(kind==='content')html=field('title','Título','text',r.title,[],true)+field('format','Formato','select',r.format||'image',['image','video','story','carousel','text'])+field('channel','Canal','select',r.channel||'instagram',['instagram','google','whatsapp','website','other'])+(r.operationId?operationLink(r):field('status','Situação','select',r.status||'draft',['draft','review','approved','scheduled']))+field('campaignId','Campanha','select',r.campaignId||'',campaignOptions())+field('assetId','Arquivo da biblioteca','select',r.assetId||'',[['','Sem arquivo'],...S.assets.filter(a=>a.mime.startsWith('image/')||a.mime.startsWith('video/')).map(a=>[a.id,a.name])])+field('caption','Legenda ou texto','textarea',r.caption)+field('visualPrompt','Briefing da imagem ou do vídeo','textarea',r.visualPrompt)+field('mediaUrl','URL HTTPS pública da mídia para publicação','url',r.mediaUrl)+field('carouselUrls','Carrossel: URLs HTTPS de 2 a 10 fotos JPEG, uma por linha','textarea',(r.carouselUrls||[]).join('\n'))+field('mediaType','Tipo da mídia','select',r.mediaType||'image',['image','video'])+field('notes','Pontos a revisar','textarea',r.notes);
 if(kind==='leads')html=field('name','Nome','text',r.name,[],true)+field('company','Empresa','text',r.company)+field('email','E-mail','email',r.email)+field('phone','WhatsApp com código do país','tel',r.phone)+field('stage','Etapa','select',r.stage||'new',leadStages)+field('value','Valor da oportunidade (R$)','number',r.value)+field('source','Origem','text',r.source||'Registro manual')+field('campaignId','Campanha','select',r.campaignId||'',campaignOptions())+field('nextAction','Próximo passo','text',r.nextAction)+field('nextDate','Data do próximo passo','date',r.nextDate)+field('notes','Observações','textarea',r.notes)+field('consent','Há autorização registrada para mensagens desta empresa','checkbox',r.consent)+field('optOut','Este contato pediu para não receber mensagens','checkbox',r.optOut);
 if(kind==='tasks')html=field('title','Tarefa','text',r.title,[],true)+field('priority','Prioridade','select',r.priority||'normal',['normal','high','low'])+(r.kernelStep?operationLink(r):field('status','Situação','select',r.status||'todo',['todo','doing','done']))+field('dueDate','Prazo','date',r.dueDate)+field('campaignId','Campanha','select',r.campaignId||'',campaignOptions())+field('description','Descrição','textarea',r.description);
 if(kind==='metrics')html=field('date','Data da medição','date',r.date||new Date().toISOString().slice(0,10),[],true)+field('channel','Canal','select',r.channel||'instagram',['instagram','whatsapp','google','website','metaAds','other'])+field('campaignId','Campanha','select',r.campaignId||'',campaignOptions())+['impressions','reach','clicks','leads','sales','revenue','spend'].map(k=>field(k,{impressions:'Impressões',reach:'Alcance',clicks:'Cliques',leads:'Leads',sales:'Vendas',revenue:'Receita (R$)',spend:'Investimento (R$)'}[k],'number',r[k])).join('')+field('notes','Fonte e observações','textarea',r.notes);
 if(kind==='pages')html=field('title','Título da página','text',r.title,[],true)+field('buttonLabel','Texto do botão','text',r.buttonLabel||'Quero saber mais')+field('description','Apresentação da oferta','textarea',r.description)+field('campaignId','Campanha de origem','select',r.campaignId||'',campaignOptions())+field('active','Página disponível','checkbox',r.active!==false);
 if(kind==='knowledge')html=field('title','Título','text',knowledgeTitle(r.title),[],true)+field('source','Fonte ou responsável','text',r.source)+field('text','Informações confirmadas','textarea',r.text,[],true);
 formDialog((id?'Editar ':'Criar ')+titles[kind].toLowerCase(),html,async d=>{if(kind==='content')d.carouselUrls=d.carouselUrls.split('\n').map(x=>x.trim()).filter(Boolean);if(kind==='campaigns')d.channels=d.channels.split(',').map(s=>s.trim()).filter(Boolean);if(r.operationId&&(kind!=='tasks'||r.kernelStep)){delete d.status;delete d.scheduledAt;}if(id)d.version=r.version;await api(endpoint('records/'+kind+(id?'/'+id:'')),id?'PATCH':'POST',d);},'Salvar',true);
 if(id&&!r.operationId)$('#dialog-form .form-footer').insertAdjacentHTML('beforeend',`<button type="button" class="danger-link" data-action="delete-record" data-kind="${kind}" data-id="${id}">Remover</button>`);
}
function startCompanyDiagnosis(){
 const activeCompany=org,idempotencyKey=crypto.randomUUID();
 formDialog('Diagnóstico da empresa','<div class="dialog-explainer wide"><p>A análise usa as informações já salvas da sua empresa e apresenta recomendações e perguntas. Não consulta fontes externas nem altera o cadastro.</p><small>Esta ação usa IA. Salvar o cadastro, por si só, não inicia a análise.</small></div>'+field('brief','Direção da análise','textarea',COMPANY_DIAGNOSIS_BRIEF,[],true),async d=>{
  if(org!==activeCompany)throw new Error('A empresa ativa mudou. Abra novamente o diagnóstico.');
  await api('/api/portal/'+activeCompany+'/jobs','POST',{kind:'agent',payload:{agent:'strategy',purpose:'company_diagnosis',brief:d.brief},idempotencyKey});
 },'Iniciar análise');
}
